function _RA_mul(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
function _RA_hash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619);}return h>>>0;}
function _RA_arrange(rootPc, mode, character, tempo, seedStr){
  const rng=_RA_mul(_RA_hash(seedStr||(mode+character)));
  const pick=arr=>arr[Math.floor(rng()*arr.length)];
  const prog=_RA_PROG[mode+'|'+character]||_RA_PROG[mode+'|gentle']||_RA_PROG['major|gentle'];
  const scale=_RA_SCALE[mode]||_RA_SCALE.major;
  const scaleSet=new Set(scale.map(x=>(x+rootPc)%12));
  const bars=prog.map(([off,type])=>({rootPc:(rootPc+off)%12,type,tones:_RA_CHORD[type].map(iv=>(rootPc+off+iv)%12)}));
  const notes=[];
  const add=(m,b,d)=>notes.push({note:noteName(m),dur:d,beat:+b.toFixed(3)});
  const bassMidi=pc=>{let m=36+pc;if(m>43)m-=12;return m;};
  const voic=(pc,type)=>{let base=48+pc;if(base>59)base-=12;return _RA_CHORD[type].map(iv=>base+iv);};
  // BASS
  const bs=_RA_BASS[character];
  for(let i=0;i<8;i++){const base=i*4;const R=bassMidi(bars[i].rootPc);const NR=bassMidi(bars[(i+1)%8].rootPc);
    if(bs==='walk'){add(R,base,1);add(R+7,base+1,1);add(R,base+2,1);add(NR-1,base+3,1);}
    else if(bs==='ost'){for(let k=0;k<8;k++)add(R,base+k*0.5,0.5);}
    else if(bs==='grand'){add(R,base,2);add(R+12,base+2,2);}
    else if(bs==='arp'){add(R,base,1.5);add(R+7,base+1.5,1.5);add(R+12,base+3,1);}
    else if(bs==='spar'){add(R,base,4);}
    else {add(R,base,4);add(R+12,base+2,2);}
  }
  // COMP
  const cs=_RA_COMP[character];
  for(let i=0;i<8;i++){const base=i*4;const V=voic(bars[i].rootPc,bars[i].type);
    if(cs==='off'){for(const n of V)add(n,base,0.25);for(const off of[0.5,1.5,2.5,3.5])for(const n of V)add(n,base+off,0.25);}
    else if(cs==='pow'){const pw=[V[0],V[0]+7];add(pw[0],base,0.25);for(const off of[0.5,1.5,2.5,3.5])for(const n of pw)add(n,base+off,0.25);}
    else if(cs==='rich'){for(const n of V)add(n,base,4);}
    else if(cs==='spar'){add(V[0],base,4);if(V[1])add(V[1],base+2,2);}
    else {add(V[0],base,1.5);if(V[1])add(V[1],base+1.5,1.5);if(V[2])add(V[2],base+3,1);}
  }
  // MELODY (motif → arc to bar4 climax → cadence)
  const center=_RA_CENTER[character]||72; const ceil=center+13, floor=center-11;
  const inScale=m=>scaleSet.has(((m%12)+12)%12);
  const cands=(tp)=>{const a=[];for(let m=floor;m<=ceil;m++)if(tp.has(((m%12)+12)%12))a.push(m);return a;};
  const pickTone=(cur,tp,target,avoid)=>{const a=cands(tp);if(!a.length)return cur;a.sort((x,y)=>(Math.abs(x-target)+0.6*Math.abs(x-cur)+rng()*0.4)-(Math.abs(y-target)+0.6*Math.abs(y-cur)+rng()*0.4));for(const m of a){if(m!==avoid)return m;}return a[0];};
  const stepScale=(cur,dir)=>{let m=cur+dir;for(let k=0;k<3;k++){if(inScale(m))return m;m+=dir;}return cur+dir;};
  let prev=center; const rhy=_RA_RHY[character]||_RA_RHY.gentle; const cell0=pick(rhy);
  for(let i=0;i<8;i++){const base=i*4;const tp=new Set(bars[i].tones);const target=center+_RA_LIFT[i];
    const cell=(i===0||i===2)?cell0:(i===7?[2,1,1]:pick(rhy)); let b=base;
    for(let j=0;j<cell.length;j++){const d=cell[j];const rel=+(b-base).toFixed(3);const strong=(rel%2===0);
      let pitch;
      if(i===7&&j===cell.length-1){pitch=pickTone(prev,new Set(bars[7].tones),center,null);}
      else if(strong){pitch=pickTone(prev,tp,target,prev);}
      else{let dir=Math.sign(target-prev)||(rng()<0.5?1:-1);if(rng()<0.22)dir=-dir;pitch=stepScale(prev,dir);if(pitch===prev)pitch=stepScale(prev,dir);if(!inScale(pitch))pitch=pickTone(prev,tp,target,prev);}
      pitch=Math.max(floor-2,Math.min(ceil,pitch)); add(pitch,b,d); prev=pitch; b+=d;
    }
  }
  return {tempo,notes};
}

// Generate a piece (~32 beats) from a free-text mood. Returns a song object
// shaped like SONG_LIBRARY entries: {mood,title,tempo,notes:[{note,dur,beat}]}.
// Uses the rich arranger above, with mode+character inferred from the mood's
// valence/energy profile — so any typed mood gets a full-bodied composition.
function moodToSong(text){
  const label=(text||'').trim(); if(!label) return null;
  const P=_moodParams(label.toLowerCase());
  const v=P.v, e=P.e;
  const mode = (v>=0.5 && e>0.7) ? 'lydian' : (v>=0 ? 'major' : 'minor');
  let ch;
  if(mode==='lydian') ch='dreamy';
  else if(v<=-0.2 && e<0.4) ch='eerie';
  else if(e>=0.7 && v<0) ch='aggressive';
  else if(e>=0.7 && v>=0.4) ch='bright';
  else if(e>=0.7) ch='driving';
  else if(e>=0.5 && v>=0.6) ch='grand';
  else if(e>=0.5 && v>=0.25) ch='bright';
  else if(e>=0.45 && v<0) ch='driving';
  else if(e<0.4 && v<-0.05) ch='sad';
  else ch = v<0 ? 'sad' : 'gentle';
  const out=_RA_arrange(P.root, mode, ch, P.tempo, label.toLowerCase());
  return { mood:label, title:label.charAt(0).toUpperCase()+label.slice(1), tempo:out.tempo, notes:out.notes };
}

// Atmosphere transform: re-colour an image's literal colour→notes piece with a
// detected mood (valence v / energy e). Snaps pitches to the mood scale (harmony),
// scales velocity (dynamics) and time (tempo). Returns NEW events; pass the literal
// events each time so toggling off restores the original.
function _atmoTransform(evts, mood){
  if(!evts||!evts.length||!mood) return evts;
  const v=Math.max(-1,Math.min(1,mood.v||0)), e=Math.max(0,Math.min(1,mood.e==null?0.5:mood.e));
  const sm=(v>=0.5&&e>0.7)?'lydian':(v>=0?'major':'minor');
  const SC=({major:[0,2,4,5,7,9,11],minor:[0,2,3,5,7,8,10],lydian:[0,2,4,6,7,9,11]})[sm];
  const root=((mood.root||0)%12+12)%12;
  const tempoK=1.35-e*0.8;     // calm → slower, intense → faster
  const vScale=0.6+e*0.6;      // calm → softer, intense → louder
  const snap=(m)=>{ const pc=((m-root)%12+12)%12; let best=SC[0],bd=99; for(const d of SC){ const dd=Math.min(((pc-d)%12+12)%12,((d-pc)%12+12)%12); if(dd<bd){bd=dd;best=d;} } let delta=((best-pc)%12+12)%12; if(delta>6) delta-=12; return m+delta; };
  return evts.map(ev=>({ ...ev, startMs:Math.round((ev.startMs||0)*tempoK), n:(ev.n||[]).map(no=>({ ...no, m:snap(no.m), v:Math.max(20,Math.min(124,Math.round((no.v||80)*vScale))), durMs:Math.max(40,Math.round((no.durMs||300)*tempoK)) })) }));
}

// Crossfade-morph two mood pieces into one. First half is mood A,
// second half is mood B (time-scaled to A's length), with a velocity
// crossfade in the 40-60% zone where both pieces overlap and blend.
function morphSongs(songA, songB) {
  if (!songA || !songB) return null;
  const aNotes = songA.notes;
  const bNotes = songB.notes;
  const aMax = Math.max(...aNotes.map(n => n.beat + n.dur));
  const bMax = Math.max(...bNotes.map(n => n.beat + n.dur));
  const bScale = aMax / bMax;
  const fadeStart = aMax * 0.40;
  const fadeEnd   = aMax * 0.60;
  const merged = [];
  for (const n of aNotes) {
    if (n.beat >= fadeEnd) continue;
    let factor = 1;
    if (n.beat > fadeStart) factor = 1 - (n.beat - fadeStart) / (fadeEnd - fadeStart);
    if (factor <= 0.15) continue;
    merged.push({ ...n, _vScale: factor });
  }
  for (const n of bNotes) {
    const scaledBeat = n.beat * bScale;
    if (scaledBeat < fadeStart) continue;
    let factor = 1;
    if (scaledBeat < fadeEnd) factor = (scaledBeat - fadeStart) / (fadeEnd - fadeStart);
    if (factor <= 0.15) continue;
    merged.push({ ...n, beat: scaledBeat, _vScale: factor });
  }
  merged.sort((a, b) => a.beat - b.beat);
  return {
    notes: merged,
    tempo: Math.round((songA.tempo + songB.tempo) / 2),
    title: songA.mood + ' → ' + songB.mood
  };
}

// Chain-morph through a sequence of moods: A → B → C → D. Each consecutive pair
// crossfades like morphSongs, and the segments are laid end-to-end so the piece
// travels through every chosen mood in order. `songs` is an array of song objects
// (length 2..4: the current mood followed by 1–3 targets).
function morphChain(songs) {
  if (!songs || songs.length < 2) return null;
  const valid = songs.filter(Boolean);
  if (valid.length < 2) return null;
  // Build each A→B segment, then concatenate by offsetting each segment's beats
  // to start where the previous one ended.
  const out = [];
  let beatOffset = 0;
  let tempoSum = 0, tempoN = 0;
  const titleParts = [valid[0].mood];
  for (let i = 0; i < valid.length - 1; i++) {
    const seg = morphSongs(valid[i], valid[i + 1]);
    if (!seg) continue;
    const segMax = Math.max(...seg.notes.map(n => n.beat + n.dur), 0);
    for (const n of seg.notes) out.push({ ...n, beat: n.beat + beatOffset });
    beatOffset += segMax;
    tempoSum += seg.tempo; tempoN++;
    titleParts.push(valid[i + 1].mood);
  }
  if (!out.length) return null;
  return {
    notes: out,
    tempo: Math.round(tempoSum / Math.max(1, tempoN)),
    title: titleParts.join(' → ')
  };
}


// Reroll: transform a piece with random transposition, octave swaps, and
// rhythmic jitter. Preserves structure & beat positions, varies surface details.
function rerollSong(song, structureStable) {
  if (!song) return null;
  // Random transpose ±5 semitones, guaranteed nonzero
  let t;
  do { t = Math.floor(Math.random() * 11) - 5; } while (t === 0);
  const newNotes = song.notes.map(n => {
    const midi = name2midi(n.note);
    if (!midi) return n;
    let newMidi = midi + t;
    // Octave swaps + rhythmic jitter change the chord GROUPING (= structure).
    // When structureStable (Random OFF) we keep them off so only pitch — and
    // therefore only COLOR — changes; the painting's composition is preserved.
    if (!structureStable && midi > 48 && Math.random() < 0.15) {
      newMidi += Math.random() < 0.5 ? -12 : 12;
    }
    // Clamp to full piano range after all transformations
    newMidi = Math.max(21, Math.min(108, newMidi));
    const durMul = structureStable ? 1 : (0.85 + Math.random() * 0.3);
    return {
      note: noteName(newMidi),
      dur: structureStable ? n.dur : Math.max(0.25, n.dur * durMul),
      beat: n.beat
    };
  });
  return {
    notes: newNotes,
    // Tempo changes scale startMs and reshuffle chord grouping → structure.
    // Keep tempo fixed when structureStable.
    tempo: structureStable ? song.tempo : Math.max(50, song.tempo + (Math.floor(Math.random() * 21) - 10)),
    title: song.title
  };
}

// ─── Memoized keyboard keys ───────────────────────────────────────────────
// The keyboard renders 52 white + 36 black keys. Before this extraction those
// 88 divs re-rendered on every parent state change — including the 5-15Hz
// `disp` tick during playback. Now each key has primitive props plus stable
// callback refs only; React.memo skips reconciliation when nothing relevant
// for THAT key changed.
//
// pressNote / releaseNote / setHoveredKey come from useCallback/useState and
// have stable identity. pressInfo is a ref. snapped/busy/loadedMode are
// primitives. The on-mouse/on-touch handlers are recreated per render of the
// child, but that's fine — they only matter when the child actually renders,
// which memo gates.

// ─────────────────────────────────────────────────────────────────────────────
